// @name Mahjong solitaire
// @background #23463f
// @refresh 3600
// Mahjong solitaire: take matching pairs of free tiles away until the board
// is empty. A tile is free when no tile lies on it and its left or right side
// is open. Every deal can be won. The board is one drawing; a tap on it finds
// the top tile under the finger. The game in progress is kept in the scene's
// state, so it outlasts a restart.
import { LAYOUTS, freePairs, isFree, neighbours, newGame, places, readGame, shuffleRemaining, tapTile, tilesLeft, undo } from './logic'

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

const THEMES = {
  color: {
    page: 'bg-[#23463f] text-[#f3eee2]',
    muted: 'text-[#a9c3b9]',
    button: 'bg-[#2f5d53] text-[#f3eee2] active:bg-[#3a6e62]',
    off: 'bg-[#2a5249] text-[#6f948a]',
    primary: 'bg-[#d39a3c] text-[#24302b] active:bg-[#b9832c]',
    card: 'bg-[#fbf7ee] text-[#24302b] border-4 border-[#d39a3c]',
    cardButton: 'bg-[#e9e1d0] text-[#24302b]',
    face: '#fbf7ee',
    blocked: '#e4dccb',
    side: '#b49a6c',
    edge: '#6f5e42',
    selected: '#f3cf6a',
    hint: '#2f8f83',
    ink: ['#2f4f86', '#2f7350', '#a6342b'], // dots, bamboo, characters
    wind: '#2b2f3a',
    dragons: ['#a6342b', '#2f7350', '#2f4f86'],
    flower: '#7d3f7d',
    season: '#b9771c',
    number: '#2b2f3a',
  },
  high: {
    page: 'bg-white text-black',
    muted: 'text-black',
    button: 'bg-white text-black border-2 border-black',
    off: 'bg-white text-black border-2 border-black opacity-30',
    primary: 'bg-black text-white',
    card: 'bg-white text-black border-4 border-black',
    cardButton: 'bg-white text-black border-2 border-black',
    face: '#ffffff',
    blocked: '#ffffff',
    side: '#000000',
    edge: '#000000',
    selected: '#000000',
    hint: '#000000',
    ink: ['#000000', '#000000', '#000000'],
    wind: '#000000',
    dragons: ['#000000', '#000000', '#000000'],
    flower: '#000000',
    season: '#000000',
    number: '#000000',
  },
}

// The faces' pictures, each one path in a 24 x 24 box, filled even-odd.
const DOT = 'M12 2.5a9.5 9.5 0 1 0 0 19 9.5 9.5 0 1 0 0-19zm0 5a4.5 4.5 0 1 1 0 9 4.5 4.5 0 1 1 0-9z'
const BAMBOO = 'M8.5 1h7v6.5h-7zM8.5 8.75h7v6.5h-7zM8.5 16.5h7V23h-7z'
const CHARACTER = 'M3 3h18v18H3zM6 6v12h12V6zM8.5 8.5h7v2h-7zM8.5 13.5h7v2h-7z'
const DRAGONS = [
  // red: a box crossed by a bar
  'M10.5 1h3v5H21v10h-7.5v7h-3v-7H3V6h7.5zM6 9v4h4.5V9zm7.5 0v4H18V9z',
  // green: a leaf
  'M12 1.5c5.5 4.5 8 10 4.5 15.5-1.2 1.9-3 3-4.5 5.5-1.5-2.5-3.3-3.6-4.5-5.5C4 11.5 6.5 6 12 1.5zM12 6.5c-2.6 2.8-3.6 6-2 9 .6 1.1 1.3 1.8 2 2.8.7-1 1.4-1.7 2-2.8 1.6-3 .6-6.2-2-9z',
  // white: a frame
  'M3 1.5h18v21H3zM5.5 4v16h13V4zM8 6.5h8v11H8zM9.75 8.25v7.5h4.5v-7.5z',
]
const FLOWER = 'M12 2a4 4 0 1 1 0 8 4 4 0 1 1 0-8zM12 14a4 4 0 1 1 0 8 4 4 0 1 1 0-8zM2 12a4 4 0 1 1 8 0 4 4 0 1 1-8 0zM14 12a4 4 0 1 1 8 0 4 4 0 1 1-8 0z'
const SEASON = 'M12 7a5 5 0 1 1 0 10 5 5 0 1 1 0-10zM11 1h2v4h-2zM11 19h2v4h-2zM1 11h4v2H1zM19 11h4v2h-4zM4.2 5.6l1.4-1.4 2.8 2.8-1.4 1.4zM15.6 17l1.4-1.4 2.8 2.8-1.4 1.4zM4.2 18.4l2.8-2.8 1.4 1.4-2.8 2.8zM15.6 7l2.8-2.8 1.4 1.4-2.8 2.8z'
const WINDS = ['E', 'S', 'W', 'N']

const ICONS = {
  hint: 'M12,2A7,7 0 0,0 5,9C5,11.38 6.19,13.47 8,14.74V17A1,1 0 0,0 9,18H15A1,1 0 0,0 16,17V14.74C17.81,13.47 19,11.38 19,9A7,7 0 0,0 12,2M9,21A1,1 0 0,0 10,22H14A1,1 0 0,0 15,21V20H9V21Z',
  shuffle: 'M17,3L22.25,7.5L17,12L22.25,16.5L17,21V18H14.26L11.44,15.18L13.56,13.06L15.5,15H17V12L17,9H15.5L6.5,18H2V15H5.26L14.26,6H17V3M2,6H6.5L9.32,8.82L7.2,10.94L5.26,9H2V6Z',
  undo: 'M12.5,8C9.85,8 7.45,9 5.6,10.6L2,7V16H11L7.38,12.38C8.77,11.22 10.54,10.5 12.5,10.5C16.04,10.5 19.05,12.81 20.1,16L22.47,15.22C21.08,11.03 17.15,8 12.5,8Z',
  new: 'M19,13H13V19H11V13H5V11H11V5H13V11H19V13Z',
}

// The tile's width over its height, how far a layer is raised (up and left),
// and how deep a tile's edge shows, as parts of the tile's width.
const ASPECT = 0.8
const LIFT = 0.15
const DEPTH = 0.15

/** How big a tile can be for a layout in a box, and the board's size at that. */
const fit = (layout, boxW, boxH) => {
  const ps = places(layout)
  let maxX = 0
  let maxY = 0
  let maxZ = 0
  for (const p of ps) {
    maxX = Math.max(maxX, p.x + 2)
    maxY = Math.max(maxY, p.y + 2)
    maxZ = Math.max(maxZ, p.z)
  }
  const cols = maxX / 2
  const rows = maxY / 2
  const extra = DEPTH + maxZ * LIFT
  const w = Math.floor(Math.min(boxW / (cols + extra), boxH / (rows / ASPECT + extra)))
  return { w, h: Math.round(w / ASPECT), cols, rows, maxZ }
}

const LAYOUT_ORDER = ['turtle', 'pyramid', 'small']
/** The layout setting, with "auto" the biggest whose tiles are still a finger wide. */
const chooseLayout = (app, boxW, boxH) => {
  const wanted = app.state.layout || 'auto'
  if (LAYOUTS[wanted]) return wanted
  for (const name of LAYOUT_ORDER) if (fit(name, boxW, boxH).w >= 36) return name
  return 'small'
}

// What a tap changes is signals: each tile's look, the counts, the note and
// the card over the board. A tap runs only the components that read them, not
// get().
const tiles = Array.from({ length: 144 }, () => signal(''))
const info = signal({ left: 0, pairs: 0, wins: 0, shuffles: 0, hints: 0, canUndo: false, confirm: false })
const message = signal('')
// The game on the board (get() reads it from the scene's state, a tap plays
// on it), its places, which tiles touch, and whether blocked tiles are shaded.
let game = null
let ps = []
let nb = null
let shade = false

const loadGame = (app, layout) => {
  const kept = readGame(app.state.game)
  if (kept && kept.layout === layout) return kept
  const game = newGame(layout, Date.now() % 2147483647, kept ? kept.wins : 0)
  frameos.setState('game', game)
  return game
}

// The signals from the game and what is remembered beside it. A signal set
// to what it holds already wakes nothing.
const sync = () => {
  const hint = frameos.recall('hint')
  for (let i = 0; i < ps.length; i++) {
    let look = 'plain'
    if (i === game.selected) look = 'selected'
    else if (Array.isArray(hint) && (hint[0] === i || hint[1] === i)) look = 'hint'
    else if (shade && !isFree(i, game.gone, nb)) look = 'blocked'
    const tile = game.gone[i] ? '' : `${look} ${game.faces[i]}`
    if (tiles[i].peek() !== tile) tiles[i].value = tile
  }
  const left = tilesLeft(game)
  const now = {
    left,
    pairs: left ? freePairs(game, nb).length : 0,
    wins: game.wins,
    shuffles: game.shuffles,
    hints: game.hints,
    canUndo: game.history.length >= 2,
    confirm: !!frameos.recall('confirm'),
  }
  const was = info.peek()
  if (Object.keys(now).some((key) => now[key] !== was[key])) info.value = now
  const text = frameos.recall('note') || ''
  if (message.peek() !== text) message.value = text
}

const note = (text) => frameos.remember('note', text)
const count = (n, word) => (n === 0 ? `no ${word}s` : n === 1 ? `1 ${word}` : `${n} ${word}s`)

/** One tile: its edge, its face, and the face's picture. */
const tileArt = (face, x, y, w, h, t, look) => {
  const r = Math.max(2, w * 0.12)
  const depth = Math.max(2, w * DEPTH)
  const lit = look === 'selected'
  const ink = (color) => (lit ? (t === THEMES.high ? '#ffffff' : color) : color)
  const fill = lit ? t.selected : look === 'blocked' ? t.blocked : t.face
  const parts = [
    <rect x={x + depth} y={y + depth} width={w} height={h} rx={r} fill={t.side} />,
    <rect x={x} y={y} width={w} height={h} rx={r} fill={fill} stroke={look === 'hint' ? t.hint : t.edge}
      strokeWidth={look === 'hint' ? Math.max(3, w * 0.1) : Math.max(1, w * 0.03)} />,
  ]
  const icon = (d, color, size, ix, iy) => (
    <path d={d} fill={ink(color)} fillRule="evenodd" transform={`translate(${ix.toFixed(1)} ${iy.toFixed(1)}) scale(${(size / 24).toFixed(3)})`} />
  )
  const number = (text, size, color) => (
    <text x={x + w * 0.1} y={y + size * 0.95} fontSize={size} fontWeight="bold" fill={ink(color)}>{text}</text>
  )
  if (face < 27) {
    // A suit: its number in the corner, its picture below.
    const suit = Math.floor(face / 9)
    const size = w * 0.6
    parts.push(number(String((face % 9) + 1), h * 0.36, t.number))
    parts.push(icon([DOT, BAMBOO, CHARACTER][suit], t.ink[suit], size, x + w - size - w * 0.08, y + h - size - h * 0.07))
  } else if (face < 31) {
    parts.push(
      <text x={x + w / 2} y={y + h * 0.7} fontSize={h * 0.56} fontWeight="bold" textAnchor="middle" fill={ink(t.wind)}>
        {WINDS[face - 27]}
      </text>,
    )
  } else if (face < 34) {
    const size = w * 0.82
    parts.push(icon(DRAGONS[face - 31], t.dragons[face - 31], size, x + (w - size) / 2, y + (h - size) / 2))
  } else {
    // Flowers and seasons: any flower takes any flower, so each has a number too.
    const flower = face < 38
    const size = w * 0.66
    parts.push(number(String(((face - 34) % 4) + 1), h * 0.26, t.number))
    parts.push(icon(flower ? FLOWER : SEASON, flower ? t.flower : t.season, size, x + w - size - w * 0.08, y + h - size - h * 0.07))
  }
  return parts
}

const act = (fn) => {
  const copy = JSON.parse(JSON.stringify(game))
  if (fn(copy) === false) return false
  frameos.setState('game', copy)
  game = copy
  return true
}

const startOver = () => {
  frameos.remember('confirm', false)
  frameos.remember('hint', null)
  note('')
  game = newGame(game.layout, (Date.now() ^ game.seed) % 2147483647, game.wins)
  frameos.setState('game', game)
  sync()
}

const askNewGame = () => {
  if (!game.history.length || tilesLeft(game) === 0) startOver()
  else {
    frameos.remember('confirm', true)
    sync()
  }
}

const keepPlaying = () => {
  frameos.remember('confirm', false)
  sync()
}

const showHint = () => {
  const pairs = freePairs(game, nb)
  if (!pairs.length) {
    note('No pairs are free: shuffle the tiles.')
    sync()
    return true
  }
  // Each hint shows the next pair, so asking again shows another.
  const pick = pairs[game.hints % pairs.length]
  frameos.remember('hint', pick)
  note('')
  const changed = act((g) => {
    g.hints += 1
    g.selected = -1
  })
  sync()
  return changed
}

const doShuffle = () => {
  frameos.remember('hint', null)
  let ok = true
  const changed = act((g) => {
    ok = shuffleRemaining(g, ps, nb)
    return ok
  })
  note(ok ? 'Shuffled: the tiles left can all be taken.' : 'These tiles cannot all come away now: undo, or start a new game.')
  sync()
  return changed || true
}

const doUndo = () => {
  frameos.remember('hint', null)
  note('')
  const changed = act((g) => undo(g))
  sync()
  return changed
}

export function onEvent(app, context) {
  const kept = readGame(app.state.game)
  if (!kept) return false
  game = kept
  ps = places(kept.layout)
  nb = neighbours(ps)
  const p = context.payload || {}
  if (context.event === 'back') return doUndo()
  if (context.event === 'forward') return showHint()
  if (context.event !== 'keyDown' || p.ctrl || p.alt || p.meta) return false
  const key = String(p.key || '').toLowerCase()
  if (frameos.recall('confirm')) {
    if (key === 'enter' || key === 'y') startOver()
    else if (key === 'escape' || key === 'n') keepPlaying()
    else return false
    return true
  }
  if (key === 'h') return showHint()
  if (key === 's') return doShuffle()
  if (key === 'u' || key === 'backspace') return doUndo()
  if (key === 'n') {
    askNewGame()
    return true
  }
  return false
}

// Tile `i`, gone or standing.
const Tile = memo(({ i, x, y, w, h, t }) => {
  const tile = tiles[i].value
  if (!tile) return <g />
  const [look, face] = tile.split(' ')
  return <g>{tileArt(Number(face), x, y, w, h, t, look)}</g>
})

// A card over the board: the confirm, the win, or no pairs left.
const Overlay = memo(({ t, boardW, boardH }) => {
  const { left, pairs, wins, shuffles, hints, confirm } = info.value
  const cardW = Math.round(Math.min(boardW * 0.8, 520))
  const cardFont = Math.round(Math.max(18, Math.min(cardW * 0.07, 40)))
  const cardButton = (label, cls, onClick) => (
    <div className={`h-[${Math.max(48, Math.round(cardFont * 1.8))}px] px-5 rounded-xl flex items-center text-[${Math.round(cardFont * 0.7)}px] font-bold ${cls}`} onClick={onClick}>
      {label}
    </div>
  )
  const card = (title, line, actions) => (
    <div className={`absolute top-[${Math.round(boardH * 0.18)}px] left-[${Math.round((boardW - cardW) / 2)}px] w-[${cardW}px] rounded-2xl p-[${Math.round(cardFont * 0.8)}px] flex flex-col items-center gap-3 ${t.card}`}>
      <span className={`text-[${cardFont}px] font-bold text-center`}>{title}</span>
      <span className={`text-[${Math.round(cardFont * 0.6)}px] text-center`}>{line}</span>
      <div className="flex gap-3">{actions}</div>
    </div>
  )
  if (confirm) {
    return card('New game?', `${left} tiles are still on the board.`, [
      cardButton('Keep playing', t.cardButton, keepPlaying),
      cardButton('New game', t.primary, startOver),
    ])
  }
  if (left === 0) {
    return card('Cleared!', `All ${ps.length} tiles, with ${count(shuffles, 'shuffle')} and ${count(hints, 'hint')}. Games won: ${wins}.`, [
      cardButton('New game', t.primary, startOver),
    ])
  }
  if (pairs === 0) {
    return card('No pairs left', 'No two free tiles match. Shuffle the tiles left, or undo.', [
      cardButton('Undo', t.cardButton, doUndo),
      cardButton('Shuffle', t.primary, doShuffle),
    ])
  }
  // No card: an empty box, so the card can come in place of it.
  return <div className="absolute" />
})

const button = (name, label, cls, onClick, bw, bh, font) => (
  <div className={`w-[${bw}px] h-[${bh}px] rounded-xl flex flex-col items-center justify-center gap-1 ${cls}`} onClick={onClick}>
    <svg viewBox="0 0 24 24" className={`w-[${Math.round(Math.min(bh * 0.42, bw * 0.4))}px] h-[${Math.round(Math.min(bh * 0.42, bw * 0.4))}px]`}>
      <path d={ICONS[name]} fill="currentColor" />
    </svg>
    <span className={`text-[${font}px] font-bold leading-none`}>{label}</span>
  </div>
)

// Hint, Shuffle, Undo and New, each dimmed when it has nothing to do.
const Controls = memo(({ t, className, bw, bh, font }) => {
  const { left, canUndo } = info.value
  return (
    <div className={className}>
      {button('hint', 'Hint', left ? t.button : t.off, showHint, bw, bh, font)}
      {button('shuffle', 'Shuffle', left > 2 ? t.button : t.off, doShuffle, bw, bh, font)}
      {button('undo', 'Undo', canUndo ? t.button : t.off, doUndo, bw, bh, font)}
      {button('new', 'New', t.primary, askNewGame, bw, bh, font)}
    </div>
  )
})

// The tiles left and the pairs free (or the games won), in the side panel.
const Counts = memo(({ t, font }) => {
  const { left, pairs, wins } = info.value
  return (
    <div className="flex flex-col gap-1">
      <span className={`text-[${Math.round(font * 1.05)}px] font-bold leading-tight`}>{left ? `${left} tiles` : 'Cleared'}</span>
      <span className={`text-[${Math.round(font * 0.8)}px] ${t.muted}`}>{left ? `${pairs} ${pairs === 1 ? 'pair' : 'pairs'} free` : `${wins} won`}</span>
    </div>
  )
})

const Note = memo(({ t, font }) => <span className={`text-[${Math.round(font * 0.72)}px] leading-tight ${t.muted}`}>{message.value}</span>)

// The counts and the note in one line, over the board on a tall screen.
const StatusBar = memo(({ t, statusH }) => {
  const { left, pairs } = info.value
  const status = left ? `${left} tiles · ${pairs} ${pairs === 1 ? 'pair' : 'pairs'} free` : 'Cleared'
  return (
    <div className={`h-[${statusH}px] flex items-center gap-3`}>
      <span className={`text-[${Math.round(statusH * 0.6)}px] font-bold`}>{status}</span>
      <span className={`flex-1 truncate text-[${Math.round(statusH * 0.45)}px] ${t.muted}`}>{message.value}</span>
    </div>
  )
})

export function get(app, context) {
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  const hc = highContrast(app)
  const t = hc ? THEMES.high : THEMES.color
  const m = Math.round(Math.min(W, H) * 0.03)
  const wide = W >= H * 1.15

  // Controls in a narrow column on the right of a wide screen, else a bar under the board.
  const panelW = wide ? Math.round(Math.max(96, Math.min(W * 0.14, 200))) : W - 2 * m
  const barH = wide ? 0 : Math.round(Math.max(64, Math.min(H * 0.1, 120)))
  const statusH = wide ? 0 : Math.round(Math.max(28, Math.min(H * 0.045, 48)))
  const boxW = wide ? W - panelW - 3 * m : W - 2 * m
  const boxH = wide ? H - 2 * m : H - barH - statusH - 4 * m

  const layout = chooseLayout(app, boxW, boxH)
  game = loadGame(app, layout)
  ps = places(layout)
  nb = neighbours(ps)
  shade = !hc && app.state.shading === 'shade'
  sync()
  const { w, h, maxZ } = fit(layout, boxW, boxH)
  const lift = w * LIFT
  const depth = Math.max(2, w * DEPTH)
  let boardW = 0
  let boardH = 0
  for (const p of ps) {
    boardW = Math.max(boardW, (p.x / 2) * w + w)
    boardH = Math.max(boardH, (p.y / 2) * h + h)
  }
  boardW = Math.ceil(boardW + depth + maxZ * lift)
  boardH = Math.ceil(boardH + depth + maxZ * lift)
  // A tile's face, in the board's pixels: higher layers sit up and to the left.
  const tileX = (p) => (p.x / 2) * w + (maxZ - p.z) * lift
  const tileY = (p) => (p.y / 2) * h + (maxZ - p.z) * lift

  // A tap: the top tile under the finger (tiles are drawn bottom layer first).
  const tap = (e) => {
    const x = e.localX
    const y = e.localY
    let hit = -1
    for (let i = ps.length - 1; i >= 0 && hit < 0; i--) {
      if (game.gone[i]) continue
      const tx = tileX(ps[i])
      const ty = tileY(ps[i])
      if (x >= tx && x < tx + w + depth && y >= ty && y < ty + h + depth) hit = i
    }
    if (hit < 0 || frameos.recall('confirm')) return
    frameos.remember('hint', null)
    act((g) => {
      const result = tapTile(g, hit, nb)
      if (result === 'blocked') note('That tile is not free: its left or right side must be open.')
      else note(result === 'matched' && freePairs(g, nb).length === 0 && tilesLeft(g) ? 'No pairs are free: shuffle the tiles.' : '')
      return result !== 'blocked' && result !== 'none'
    })
    sync()
  }

  const font = Math.round(Math.max(14, Math.min(wide ? panelW * 0.15 : barH * 0.24, 28)))
  const board = (
    <div className={`relative w-[${boardW}px] h-[${boardH}px]`} onClick={tap}>
      <svg viewBox={`0 0 ${boardW} ${boardH}`} width={boardW} height={boardH} className={`w-[${boardW}px] h-[${boardH}px]`}>
        {ps.map((p, i) => <Tile i={i} x={tileX(p)} y={tileY(p)} w={w} h={h} t={t} />)}
      </svg>
      <Overlay t={t} boardW={boardW} boardH={boardH} />
    </div>
  )

  if (wide) {
    const bh = Math.floor(Math.min((H - 2 * m - 3 * m) / 6, panelW * 0.8))
    return (
      <div className={`flex w-full h-full p-[${m}px] gap-[${m}px] ${t.page}`}>
        <div className="flex-1 flex flex-col items-center justify-center">{board}</div>
        <div className={`w-[${panelW}px] flex flex-col justify-between`}>
          <Counts t={t} font={font} />
          <Note t={t} font={font} />
          <Controls t={t} className={`flex flex-col gap-[${Math.round(m * 0.6)}px]`} bw={panelW} bh={bh} font={font} />
        </div>
      </div>
    )
  }
  const bw = Math.floor((W - 2 * m - 3 * m) / 4)
  return (
    <div className={`flex flex-col w-full h-full p-[${m}px] gap-[${m}px] ${t.page}`}>
      <StatusBar t={t} statusH={statusH} />
      <div className="flex-1 flex items-center justify-center">{board}</div>
      <Controls t={t} className={`flex gap-[${m}px]`} bw={bw} bh={barH} font={font} />
    </div>
  )
}

