// The rules of Mahjong solitaire, with no drawing.
//
// A layout is a list of places, each [x, y, z] in half-tile units (a tile
// covers x..x+2 and y..y+2 on layer z). A tile is free when nothing lies on
// it and its left or its right side is open. Two free tiles with matching
// faces can be taken away together; take them all to win.
//
// Faces are numbers: 0-8 dots 1-9, 9-17 bamboo 1-9, 18-26 characters 1-9,
// 27-30 the winds (east, south, west, north), 31-33 the dragons (red, green,
// white), 34-37 the four flowers and 38-41 the four seasons. Any flower
// matches any flower, any season any season; everything else matches only
// its own face.

export const LAYOUTS = {
  // The classic turtle: 144 tiles on five layers.
  turtle: {
    name: 'Turtle',
    rows: [
      // [layer, tile row, first column, last column]: whole-tile units
      [0, 0, 1, 12], [0, 1, 3, 10], [0, 2, 2, 11], [0, 3, 1, 12],
      [0, 4, 1, 12], [0, 5, 2, 11], [0, 6, 3, 10], [0, 7, 1, 12],
      [1, 1, 4, 9], [1, 2, 4, 9], [1, 3, 4, 9], [1, 4, 4, 9], [1, 5, 4, 9], [1, 6, 4, 9],
      [2, 2, 5, 8], [2, 3, 5, 8], [2, 4, 5, 8], [2, 5, 5, 8],
      [3, 3, 6, 7], [3, 4, 6, 7],
    ],
    // Places off the whole-tile grid, in half-tile units: the turtle's head,
    // its tail and the top tile.
    extra: [[0, 7, 0], [26, 7, 0], [28, 7, 0], [13, 7, 4]],
  },
  // 72 tiles: a stepped pyramid with bigger tiles.
  pyramid: {
    name: 'Pyramid',
    rows: [
      [0, 0, 0, 7], [0, 1, 0, 7], [0, 2, 0, 7], [0, 3, 0, 7], [0, 4, 0, 7],
      [1, 1, 1, 6], [1, 2, 1, 6], [1, 3, 1, 6],
      [2, 1, 2, 5], [2, 2, 2, 5], [2, 3, 2, 5],
    ],
    extra: [[6, 4, 3], [8, 4, 3]],
  },
  // 36 tiles for a small screen.
  small: {
    name: 'Small',
    rows: [
      [0, 0, 0, 5], [0, 1, 0, 5], [0, 2, 0, 5], [0, 3, 0, 5],
      [1, 1, 1, 4], [1, 2, 1, 4],
      [2, 1, 2, 3], [2, 2, 2, 3],
    ],
    extra: [],
  },
}

export type Place = { x: number; y: number; z: number }

/** The places of a layout, drawn in this order: layer by layer, left to right, top to bottom. */
export function places(layout: string): Place[] {
  const def = LAYOUTS[layout] || LAYOUTS.turtle
  const out: Place[] = []
  for (const [z, row, from, to] of def.rows) {
    for (let col = from; col <= to; col++) out.push({ x: col * 2, y: row * 2, z })
  }
  for (const [x, y, z] of def.extra) out.push({ x, y, z })
  out.sort((a, b) => a.z - b.z || a.x - b.x || a.y - b.y)
  return out
}

/** For each place: the places lying on it, and the places touching its left and right sides. */
export function neighbours(ps: Place[]) {
  const above: number[][] = []
  const left: number[][] = []
  const right: number[][] = []
  for (let i = 0; i < ps.length; i++) {
    above.push([])
    left.push([])
    right.push([])
  }
  for (let i = 0; i < ps.length; i++) {
    const a = ps[i]
    for (let j = 0; j < ps.length; j++) {
      if (i === j) continue
      const b = ps[j]
      const dy = Math.abs(a.y - b.y)
      if (dy >= 2) continue
      const dx = b.x - a.x
      if (b.z === a.z + 1 && Math.abs(dx) < 2) above[i].push(j)
      else if (b.z === a.z && dx === -2) left[i].push(j)
      else if (b.z === a.z && dx === 2) right[i].push(j)
    }
  }
  return { above, left, right }
}

export function isFree(i: number, gone: boolean[], nb): boolean {
  if (gone[i]) return false
  for (const j of nb.above[i]) if (!gone[j]) return false
  let leftOpen = true
  for (const j of nb.left[i]) if (!gone[j]) leftOpen = false
  if (leftOpen) return true
  for (const j of nb.right[i]) if (!gone[j]) return false
  return true
}

export const matchGroup = (face: number) => (face >= 38 ? 38 : face >= 34 ? 34 : face)
export const matches = (a: number, b: number) => matchGroup(a) === matchGroup(b)

export function nextRandom(state: { seed: number }): number {
  let t = (state.seed = (state.seed + 0x6d2b79f5) | 0)
  t = Math.imul(t ^ (t >>> 15), t | 1)
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296
}

function shuffleList(list: any[], rng: { seed: number }) {
  for (let i = list.length - 1; i > 0; i--) {
    const j = Math.floor(nextRandom(rng) * (i + 1))
    const swap = list[i]
    list[i] = list[j]
    list[j] = swap
  }
  return list
}

/**
 * Pairs of faces for `count` tiles: four of each face, the flowers and the
 * seasons as groups of four. A layout of fewer than 144 picks its groups at
 * random.
 */
export function facePairs(count: number, rng: { seed: number }): number[][] {
  const groups: number[][] = []
  for (let f = 0; f < 34; f++) groups.push([f, f, f, f])
  groups.push([34, 35, 36, 37])
  groups.push([38, 39, 40, 41])
  const chosen = count >= 144 ? groups : shuffleList(groups, rng).slice(0, Math.floor(count / 4))
  const pairs: number[][] = []
  for (const g of chosen) {
    pairs.push([g[0], g[1]])
    pairs.push([g[2], g[3]])
  }
  return shuffleList(pairs, rng)
}

/**
 * Faces for the tiles still standing (where `gone` is false) that can be played
 * to the end: the board is emptied two free places at a time, picked at
 * random, and each such pair gets a matching pair of faces. Played in that same
 * order the pairs always come away, so the deal can be won. Null when the
 * places left cannot be emptied at all (a tile left on top of another, say).
 * `order`, when given, gets that winning order.
 */
export function solvableFaces(ps: Place[], nb, gone: boolean[], pairs: number[][], rng: { seed: number }, order?: number[]): number[] | null {
  for (let attempt = 0; attempt < 40; attempt++) {
    const faces = new Array(ps.length).fill(-1)
    const taken = gone.slice()
    let left = 0
    for (const g of taken) if (!g) left++
    let p = 0
    let stuck = false
    if (order) order.length = 0
    while (left > 0) {
      const free: number[] = []
      for (let i = 0; i < ps.length; i++) if (isFree(i, taken, nb)) free.push(i)
      if (free.length < 2) {
        stuck = true
        break
      }
      const a = free[Math.floor(nextRandom(rng) * free.length)]
      let b = a
      while (b === a) b = free[Math.floor(nextRandom(rng) * free.length)]
      faces[a] = pairs[p][0]
      faces[b] = pairs[p][1]
      p++
      taken[a] = true
      taken[b] = true
      if (order) order.push(a, b)
      left -= 2
    }
    if (!stuck) return faces
  }
  return null
}

export type Game = {
  layout: string
  faces: number[]
  gone: boolean[]
  history: number[] // the places taken, two at a time, in order
  selected: number
  seed: number
  shuffles: number
  hints: number
  wins: number
  started: number
}

export function newGame(layout: string, seed: number, wins: number): Game {
  const rng = { seed: seed | 0 }
  const ps = places(layout)
  const nb = neighbours(ps)
  const gone = new Array(ps.length).fill(false)
  const faces = solvableFaces(ps, nb, gone, facePairs(ps.length, rng), rng) as number[]
  return { layout, faces, gone, history: [], selected: -1, seed: rng.seed, shuffles: 0, hints: 0, wins: wins || 0, started: Date.now() }
}

/** Every pair of free tiles that match, as [a, b]. */
export function freePairs(game: Game, nb): number[][] {
  const byGroup = {}
  for (let i = 0; i < game.faces.length; i++) {
    if (!isFree(i, game.gone, nb)) continue
    const g = matchGroup(game.faces[i])
    ;(byGroup[g] = byGroup[g] || []).push(i)
  }
  const out: number[][] = []
  for (const key in byGroup) {
    const list = byGroup[key]
    for (let a = 0; a < list.length; a++) for (let b = a + 1; b < list.length; b++) out.push([list[a], list[b]])
  }
  return out
}

export const tilesLeft = (game: Game) => game.gone.filter((g) => !g).length

/** A tap on place i: select it, take a matching pair away, or move the selection. */
export function tapTile(game: Game, i: number, nb): string {
  if (i < 0 || game.gone[i]) return 'none'
  if (!isFree(i, game.gone, nb)) return 'blocked'
  if (game.selected === i) {
    game.selected = -1
    return 'deselected'
  }
  if (game.selected >= 0 && !game.gone[game.selected] && matches(game.faces[game.selected], game.faces[i])) {
    game.gone[game.selected] = true
    game.gone[i] = true
    game.history.push(game.selected, i)
    game.selected = -1
    if (tilesLeft(game) === 0) game.wins += 1
    return 'matched'
  }
  game.selected = i
  return 'selected'
}

export function undo(game: Game): boolean {
  if (game.history.length < 2) return false
  const b = game.history.pop() as number
  const a = game.history.pop() as number
  if (tilesLeft(game) === 0) game.wins = Math.max(0, game.wins - 1)
  game.gone[a] = false
  game.gone[b] = false
  game.selected = -1
  return true
}

/**
 * Deals the faces of the tiles still standing again, so the rest can be
 * played to the end where that is possible at all. False when it is not.
 */
export function shuffleRemaining(game: Game, ps: Place[], nb): boolean {
  const rng = { seed: game.seed }
  // The faces left come in matching pairs, since tiles go two at a time.
  const byGroup = {}
  for (let i = 0; i < game.faces.length; i++) {
    if (game.gone[i]) continue
    const g = matchGroup(game.faces[i])
    ;(byGroup[g] = byGroup[g] || []).push(game.faces[i])
  }
  const pairs: number[][] = []
  for (const key in byGroup) {
    const list = byGroup[key]
    for (let k = 0; k + 1 < list.length; k += 2) pairs.push([list[k], list[k + 1]])
  }
  shuffleList(pairs, rng)
  const faces = solvableFaces(ps, nb, game.gone, pairs, rng)
  game.seed = rng.seed
  if (!faces) return false
  for (let i = 0; i < faces.length; i++) if (!game.gone[i]) game.faces[i] = faces[i]
  game.selected = -1
  game.shuffles += 1
  return true
}

export function readGame(value: any): Game | null {
  if (!value || typeof value !== 'object' || !Array.isArray(value.faces) || !Array.isArray(value.gone)) return null
  if (!LAYOUTS[value.layout] || value.faces.length !== value.gone.length) return null
  if (places(value.layout).length !== value.faces.length) return null
  return value as Game
}
